EditorApplication.delayCall+=()=>{try{
var font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");if(!font)throw new Exception("Built-in reference font unavailable");
foreach(string name in Racer.Editor.YardResetAuthoring.Scenes){var scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/"+name+".unity");var root=GameObject.Find("TEMPORARY Backyard anchor validation - no route");foreach(var text in root.GetComponentsInChildren<TextMesh>()){text.font=font;text.GetComponent<Renderer>().sharedMaterial=font.material;text.GetComponent<Renderer>().shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;text.GetComponent<Renderer>().receiveShadows=false;text.transform.localPosition=Vector3.up*4.3f-text.transform.forward*.04f;}UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);}
AssetDatabase.SaveAssets();System.IO.File.WriteAllText("Docs/YardReset/marker-font-done.txt","All 192 reference labels have an explicit built-in font and text material");
}catch(Exception e){System.IO.File.WriteAllText("Docs/YardReset/marker-font-error.txt",e.ToString());}};return "Assigning readable marker fonts";
